5	  // --- Simplest case ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	
12	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums for main items (incl. 10 % first insurance surcharge + 5 G fee) ---
16	  it.todo("a single plain sword → base premium 100 G");
