31	  // --- Item-specific modifiers ---
32	  it.todo("a cursed sword adds a 50 % risk surcharge on that item's base premium");
33	  it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge");
34	  it.todo("a sword with enchantment 4 gets no high-enchantment surcharge");
35	  it.todo("a cursed sword with enchantment 5 gets both surcharges");
36	
37	  // --- Policy-wide modifiers ---
38	  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
39	  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
40	  it.todo("the 10 % first insurance surcharge applies to every quote's items");
41	  it.todo("the customer's second contract receives a 15 % follow-up discount");
42	
43	  // --- Modifier scope on multi-item policies ---
44	  it.todo("cursed sword (100 G) + plain amulet (60 G) → curse surcharge is 50 G (50 % of the sword only)");
45	
46	  // --- Rounding in the MHPCO's favour ---
47	  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
48	  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
