57	  it.todo("a cursed sword (premium 165 G) → cap 2000 G (based on the unmodified insurance value)");
58	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only)");
59	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
60	
61	  // --- Standard claim processing ---
62	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
63	  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
64	
